"""Offline HTML visual report. Every displayed score comes from evaluation JSON."""

from __future__ import annotations

import json
from pathlib import Path
from typing import Any

from .artifacts import atomic_write
from .data import LABELS


def render_report(report: dict[str, Any], data: dict[str, Any], summary: dict[str, Any], output: str | Path) -> None:
    clouds = {label: next(r["points"] for r in data["records"] if r["label"] == label and r["slice"] == "clean" and r["split"] == "test") for label in LABELS}
    payload = json.dumps({"report": report, "clouds": clouds, "summary": summary}, allow_nan=False).replace("<", "\\u003c")
    html = HTML.replace("__PAYLOAD__", payload)
    atomic_write(output, html.encode())


